def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    work = [row[:] for row in grid]
    objects = []

    while True:
        best = None
        colors = set(v for row in work for v in row if v != background)

        for color in colors:
            # Prefix sums let us count each candidate rectangle efficiently.
            pref = [[0] * (w + 1) for _ in range(h + 1)]
            for r in range(h):
                run = 0
                for c in range(w):
                    run += work[r][c] == color
                    pref[r + 1][c + 1] = pref[r][c + 1] + run

            for r0 in range(h):
                for r1 in range(r0 + 1, h):
                    rh = r1 - r0 + 1
                    for c0 in range(w):
                        for c1 in range(c0 + 1, w):
                            cw = c1 - c0 + 1
                            area = rh * cw
                            if area < 6:
                                continue
                            count = (pref[r1 + 1][c1 + 1] - pref[r0][c1 + 1]
                                     - pref[r1 + 1][c0] + pref[r0][c0])
                            if count < 4 or 5 * count < 3 * area:
                                continue

                            # Reject rectangles with an almost-empty row or column.
                            if any(sum(work[r][c] == color for c in range(c0, c1 + 1)) * 3 < cw
                                   for r in range(r0, r1 + 1)):
                                continue
                            if any(sum(work[r][c] == color for r in range(r0, r1 + 1)) * 3 < rh
                                   for c in range(c0, c1 + 1)):
                                continue

                            candidate = (count, -area, r0, r1, c0, c1, color)
                            if best is None or candidate > best:
                                best = candidate

        if best is None:
            break

        _, _, r0, r1, c0, c1, color = best
        objects.append((r0, r1, c0, c1, color))
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                work[r][c] = background

    out = [[background] * w for _ in range(h)]
    for r0, r1, c0, c1, color in objects:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out
